font-size:10px;line-height:1.4}.tmi-perm-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:14px 0 8px}.tmi-perm-head h3{margin:0;color:#0b3142;font-size:13px}.tmi-perms{display:grid;grid-template-columns:1fr 1fr;gap:7px 16px}.tmi-perm{display:flex;align-items:flex-start;gap:7px;padding:5px 0;font-size:10px;color:#294b5b}.tmi-actions{position:sticky;bottom:0;z-index:50;display:flex;justify-content:flex-end;gap:8px;margin:16px -1px -1px;padding:9px 0;background:rgba(255,255,255,.96)}.tmi-note{padding:10px;border-radius:8px;background:#f6f8fa;color:#6f7b90;font-size:10px;line-height:1.5}.tmi-loading{padding:30px;text-align:center;color:#6f7b90}.tmi-btn.loading{opacity:.65;pointer-events:none}.tmi-btn.loading:before{content:"";width:12px;height:12px;margin-right:7px;border:2px dotted currentColor;border-radius:50%;animation:tmiSpin .75s linear infinite}@keyframes tmiSpin{to{transform:rotate(360deg)}}
