<script>
(function(){'use strict';var csrf=<?= json_encode($csrfToken,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>,api='api/team.php',userId=<?= (int)$editUserId ?>,permissions=[],member=null;
function E(id){return document.getElementById(id)}function esc(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;')}function toast(t,m){if(window.fieldplxToast)window.fieldplxToast(t,m)}function req(fd){fd.append('csrf_token',csrf);return fetch(api,{method:'POST',body:fd,credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json'}}).then(function(r){return r.text().then(function(x){var d;try{d=JSON.parse(x)}catch(e){throw new Error('Invalid server response.')}if(!r.ok||!d.success)throw new Error(d.message||'Request failed.');return d})})}
function post(a){var f=new FormData();f.append('action',a);return f}function label(p){return (p.description||p.permission_code||'Permission').replace(/^View /,'View ')}
function renderPerms(selected){var set={};(selected||[]).forEach(function(id){set[Number(id)]=1});E('permissionList').innerHTML=permissions.map(function(p){return '<label class="tmi-perm"><input type="checkbox" name="permission_ids[]" value="'+Number(p.id)+'" data-code="'+esc(p.permission_code)+'" '+(set[Number(p.id)]?'checked':'')+'><span>'+esc(label(p))+'<br><small style="color:#82909a">'+esc(p.permission_code)+'</small></span></label>'}).join('');countPerms()}
function countPerms(){var n=document.querySelectorAll('#permissionList input:checked').length;E('permCount').textContent=n+' selected'}
function choosePreset(name){document.querySelectorAll('.tmi-preset').forEach(function(x){x.classList.toggle('active',x.getAttribute('data-preset')===name)});var boxes=document.querySelectorAll('#permissionList input');E('permissionsMode').value=name==='custom'?'custom':'custom';boxes.forEach(function(b){var c=String(b.getAttribute('data-code')||''),on=false;if(name==='field')on=/^(jobs|visits|scheduling|workforce|time|notes|expenses)\./.test(c)&&!/delete/.test(c);else if(name==='senior')on=/^(jobs|visits|scheduling|workforce|time|notes|expenses|clients|quotes|invoices|payments)\./.test(c)&&!/delete/.test(c);else if(name==='lead')on=/^(jobs|visits|scheduling|workforce|time|notes|expenses|clients|quotes|invoices|payments|requests|teams)\./.test(c);else if(name==='manager')on=!/^(settings|roles)\.(delete)/.test(c);else return;b.checked=on});countPerms()}
function meta(){var f=post('meta');return req(f).then(function(d){permissions=d.permissions||[];var rs=d.roles||[],h='<option value="0">No role</option>';rs.forEach(function(r){h+='<option value="'+Number(r.id)+'">'+esc(r.name)+'</option>'});E('roleSelect').innerHTML=h;renderPerms([]);if(userId>0){var x=post('get_member');x.append('user_id',String(userId));return req(x).then(function(m){member=m.member||{};E('fullName').value=((member.first_name||'')+' '+(member.last_name||'')).trim();E('email').value=member.email||'';E('phone').value=member.phone||'';E('employeeCode').value=member.employee_code||'';E('jobTitle').value=member.job_title||'';E('laborRate').value=member.labor_rate||'';E('roleSelect').value=String(member.role_id||0);E('isAdmin').checked=Number(member.is_tenant_admin||0)===1;if(member.avatar_path)E('avatarPreview').innerHTML='<img src="'+esc(member.avatar_path)+'" alt="">';else E('avatarPreview').textContent=(String(member.first_name||'U').charAt(0)+String(member.last_name||'').charAt(0)).toUpperCase();renderPerms(m.permission_allow_ids||[]);E('permissionsMode').value=(m.permission_allow_ids||[]).length?'custom':'role'})}}).then(function(){E('loading').style.display='none';E('memberForm').style.display='block'}).catch(function(e){E('loading').textContent='Unable to load team settings.';toast('error',e.message)})}
E('permissionList').addEventListener('change',function(){E('permissionsMode').value='custom';document.querySelectorAll('.tmi-preset').forEach(function(x){x.classList.remove('active')});var c=document.querySelector('[data-preset="custom"]');if(c)c.classList.add('active');countPerms()});document.querySelectorAll('.tmi-preset').forEach(function(x){x.onclick=function(){choosePreset(x.getAttribute('data-preset'))}});
E('avatarInput').addEventListener('change',function(){var f=this.files&&this.files[0];if(!f)return;var r=new FileReader();r.onload=function(){E('avatarPreview').innerHTML='<img src="'+r.result+'" alt="">'};r.readAsDataURL(f)});
function save(assign,button){if(!E('memberForm').checkValidity()){E('memberForm').reportValidity();return}E('saveAndAssign').value=assign?'1':'0';var fd=new FormData(E('memberForm'));fd.append('csrf_token',csrf);button.disabled=true;button.classList.add('loading');req(fd).then(function(d){toast('success',d.message);setTimeout(function(){window.location.href='team.php'},550)}).catch(function(e){toast('error',e.message);button.disabled=false;button.classList.remove('loading')})}E('saveMember').onclick=function(){save(false,this)};E('saveAssign').onclick=function(){save(true,this)};meta();})();
</script>
